using System.Collections.ObjectModel; using System.Windows.Input; using KennelPro.Models.Litters; using KennelPro.Models.Reproduction; using KennelPro.Services.Dogs; using KennelPro.Services.Reproduction;
namespace KennelPro.ViewModels.Reproduction;
public class ReproductionViewModel : BaseViewModel, IQueryAttributable { readonly DogService _dogs; readonly HeatCycleService _cycles; readonly MatingService _matings; readonly LitterService _litters; Guid? _dogId; public ObservableCollection<HeatCycle> HeatCycles {get;}=new(); public ObservableCollection<Mating> Matings {get;}=new(); public ObservableCollection<Litter> Litters {get;}=new(); public ICommand RefreshCommand {get;} public ICommand BackCommand {get;} public string Title {get=>_title;set=>SetProperty(ref _title,value);} string _title="Reproduction"; public ReproductionViewModel(DogService dogs,HeatCycleService cycles,MatingService matings,LitterService litters){_dogs=dogs;_cycles=cycles;_matings=matings;_litters=litters;RefreshCommand=new Command(async()=>await LoadAsync());BackCommand=new Command(async()=>await Shell.Current.GoToAsync(".."));} public void ApplyQueryAttributes(IDictionary<string,object> q){if(q.TryGetValue("dogId",out var x)&&Guid.TryParse(x?.ToString(),out var id))_dogId=id;} public async Task LoadAsync(){HeatCycles.Clear();Matings.Clear();Litters.Clear();if(_dogId.HasValue){var dog=await _dogs.GetDogForCurrentKennelAsync(_dogId.Value);if(dog==null){await Shell.Current.DisplayAlertAsync("Error","Dog not found.","OK");return;}Title=$"Reproduction: {dog.Name}";foreach(var x in await _cycles.GetForDogAsync(dog.Id))HeatCycles.Add(x);}else{foreach(var x in await _matings.GetForCurrentKennelAsync())Matings.Add(x);foreach(var x in await _litters.GetForCurrentKennelAsync())Litters.Add(x);}} }
